using System;
using System.IO;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;
using LastRail.Run;
using LastRail.Battle;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {public sealed class BDepartureAssignmentTests {
 [Test] public void OriginalAssignmentHasIndependentImmutableReader(){Assert.NotNull(typeof(LastRail.Run.BRouteSessionController).Assembly.GetType("LastRail.Run.BDepartureAssignment"));}
 internal static JObject Packet()=>(JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-assignment-sample-20261006.json"))["packet"].DeepClone();
 internal static void Rehash(JObject p){var body=(JObject)p.DeepClone();foreach(var k in new[]{"packetHash","assignmentHash","origin","departurePinHash","runtimeProfileHash","startSnapshotHash"})body.Remove(k);p["assignmentHash"]=BDirectAttackInput.Digest(body).Substring(7);body=(JObject)p.DeepClone();body.Remove("packetHash");p["packetHash"]=BDirectAttackInput.Digest(body).Substring(7);}
 internal static BDepartureAssignment Read(JObject p)=>BDepartureAssignment.Read(p.ToString(),(string)p["packetHash"],"a","LOCAL_NEW_B_PIN_19");
 [Test] public void PreservesFixedPhysicalHolesCargoAndPermanentOwnedStats(){var p=Packet();var source=Read(p);Assert.AreEqual(1,source.Actors.Count);Assert.AreEqual(1904,(long)source.Actors[0].PermanentStats["maxHp"]);Assert.AreEqual("physical-0",source.Actors[0].CarriageInstanceId);Assert.AreEqual("CARGO",(string)source.CarAtPhysicalSlot(4)["occupant"]["kind"]);Assert.IsNull(source.CarAtPhysicalSlot(1));source.Actors[0].PermanentStats["maxHp"]=1;source.Capture()["selectionRevision"]=999;Assert.AreEqual(1904,(long)source.Actors[0].PermanentStats["maxHp"]);Assert.IsTrue(JToken.DeepEquals(p,source.Capture()));Assert.IsFalse(source.CanStart);Assert.Throws<InvalidOperationException>(()=>source.RequireRuntimeBinding());}
 [TestCase("run"),TestCase("origin"),TestCase("actorSlot"),TestCase("instance"),TestCase("cargoActor"),TestCase("revisionString"),TestCase("owned"),TestCase("skills"),TestCase("profile"),TestCase("negativeAttack"),TestCase("effective"),TestCase("authority"),TestCase("duplicateSlot"),TestCase("sourceStatus"),TestCase("definition"),TestCase("unknownField")]
 public void RejectsRehashedMixedOrUnsupportedOriginalAssignments(string kind){var p=Packet();var a=p["actors"][0];switch(kind){case "run":p["runId"]="foreign";break;case "origin":p["origin"]["accountId"]="foreign";break;case "actorSlot":a["physicalSlot"]=4;break;case "instance":a["carriageInstanceId"]="other";break;case "cargoActor":((JArray)p["actors"]).Add(a.DeepClone());break;case "revisionString":a["physicalRevision"]="1";break;case "owned":a["owned"]["operatorId"]="op_sable";break;case "skills":a["skills"]=new JArray();break;case "profile":a["profileVersion"]="other";break;case "negativeAttack":a["stats"]["attack"]["numerator"]="-1";break;case "effective":a["effectiveStats"]=new JObject();break;case "authority":p["canStart"]=true;break;case "duplicateSlot":p["refitSnapshot"]["refit"]["cars"][1]["slot"]=0;break;case "sourceStatus":p["catalog"]["status"]="ISOLATED_LOCAL_FIXTURE";break;case "definition":p["definition"]["canStart"]=true;break;case "unknownField":p["nativeContextId"]="invented";break;}Rehash(p);Assert.Throws<ArgumentException>(()=>Read(p));}
 [Test] public void RequiresPacketAndIndependentEtag(){var p=Packet();Assert.Throws<ArgumentException>(()=>BDepartureAssignment.Read(p.ToString(),new string('0',64),"a","LOCAL_NEW_B_PIN_19"));p["selectionRevision"]=2;Assert.Throws<ArgumentException>(()=>Read(p));}
 [Test] public async Task ControllerStoresOneOriginalSourceAndRejectsFrozenReplacement(){using(var c=new BRouteSessionController("a","LOCAL_NEW_B_PIN_19")){var before=c.Capture();Assert.IsTrue(await c.ReadDepartureAssignmentAsync(_=>Task.FromResult(Read(Packet()))));Assert.IsTrue(JToken.DeepEquals(before,c.Capture()));var p=Packet();p["catalog"]["revision"]=2;Rehash(p);Assert.ThrowsAsync<ArgumentException>(async()=>await c.ReadDepartureAssignmentAsync(_=>Task.FromResult(Read(p))));Assert.AreEqual((string)Packet()["packetHash"],c.DepartureAssignment.PacketHash);}}
 [TestCase("Unbind"),TestCase("Bind"),TestCase("Dispose")]
 public async Task ControllerInvalidationPreventsLateSourcePublication(string action){var c=new BRouteSessionController("a","LOCAL_NEW_B_PIN_19");var pending=new TaskCompletionSource<BDepartureAssignment>();CancellationToken seen=default;var operation=c.ReadDepartureAssignmentAsync(ct=>{seen=ct;return pending.Task;});if(action=="Unbind")c.Unbind();else if(action=="Bind")c.Bind(_=>Assert.Fail("Late view notification"));else c.Dispose();Assert.IsTrue(seen.IsCancellationRequested);pending.SetResult(Read(Packet()));Assert.IsFalse(await operation);if(action!="Dispose")Assert.IsNull(c.DepartureAssignment);c.Dispose();}
 [Test] public async Task CallerCancellationDoesNotPublishSource(){using(var c=new BRouteSessionController("a","LOCAL_NEW_B_PIN_19"))using(var ct=new CancellationTokenSource()){var pending=new TaskCompletionSource<BDepartureAssignment>();var read=c.ReadDepartureAssignmentAsync(_=>pending.Task,ct.Token);ct.Cancel();pending.SetResult(Read(Packet()));Assert.ThrowsAsync(Is.InstanceOf<OperationCanceledException>(),async()=>await read);Assert.IsNull(c.DepartureAssignment);}}
 [Test] public async Task UnbindRejectsReadReenteredFromCancellationCallback(){using(var c=new BRouteSessionController("a","LOCAL_NEW_B_PIN_19")){var old=new TaskCompletionSource<BDepartureAssignment>();Task<bool> reentered=null;CancellationTokenRegistration registration=default;try{var first=c.ReadDepartureAssignmentAsync(ct=>{registration=ct.Register(()=>reentered=c.ReadDepartureAssignmentAsync(_=>Task.FromResult(Read(Packet()))));return old.Task;});c.Unbind();old.SetResult(Read(Packet()));Assert.IsFalse(await first);Assert.NotNull(reentered);Exception rejection=null;try{await reentered;}catch(Exception error){rejection=error;}Assert.IsInstanceOf<InvalidOperationException>(rejection);Assert.IsNull(c.DepartureAssignment);}finally{registration.Dispose();}}}
 [Test] public async Task NewerReadSupersedesOlderReadAndMixedRunIsRejected(){using(var c=new BRouteSessionController("a","LOCAL_NEW_B_PIN_19")){var pending=new TaskCompletionSource<BDepartureAssignment>();var first=c.ReadDepartureAssignmentAsync(_=>pending.Task);Assert.IsTrue(await c.ReadDepartureAssignmentAsync(_=>Task.FromResult(Read(Packet()))));pending.SetResult(Read(Packet()));Assert.IsFalse(await first);}using(var c=new BRouteSessionController("a","LOCAL_B12_RUN")){Assert.ThrowsAsync<ArgumentException>(async()=>await c.ReadDepartureAssignmentAsync(_=>Task.FromResult(Read(Packet()))));}}
 [Test] public async Task OriginalCombatRouteDoesNotAcceptSeparateAssignmentRun(){var method=typeof(BRuntimeObservationDeliveryTests).GetMethod("ShortSession",BindingFlags.Static|BindingFlags.NonPublic);using(var c=await (Task<BRouteSessionController>)method.Invoke(null,null)){Assert.Throws<ArgumentException>(()=>Read(Packet()).RequireSameDeparture(c.Route));Assert.ThrowsAsync<ArgumentException>(async()=>await c.ReadDepartureAssignmentAsync(_=>Task.FromResult(Read(Packet()))));}}
}}
